{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.FACT_PARETO_TARGET_PERFORMANCE_SUMMARY AS WITH MASTER_DATA AS ( SELECT * REPLACE (UPPER(TRIM(CATEGORY)) AS CATEGORY) FROM SNITCH_DB.MAPLEMONK.FACT_PARETO_TARGET_PERFORMANCE_MASTER WHERE REPORT_MONTH >= \'2026-04\' AND UPPER(TRIM(CATEGORY)) NOT IN (\'NT\', \'CB\', \'OTHERS\', \'NA\', \'\') ), CATEGORY_AGGREGATES AS ( SELECT REPORT_MONTH, HIERARCHY_LEVEL, LOCATION_ID, CATEGORY, SUM(STORE_INV_UNITS_CLOSING) AS CAT_INV_CLOSING, SUM(SALES_UNITS) AS CAT_SALES_UNITS, SUM(SALES_REVENUE) AS CAT_SALES_REVENUE, SUM(ACTUAL_REVENUE) AS CAT_ACTUAL_REVENUE FROM MASTER_DATA GROUP BY 1, 2, 3, 4 ), CATEGORY_PERF_CALC AS ( SELECT REPORT_MONTH, HIERARCHY_LEVEL, LOCATION_ID, CATEGORY, CAT_SALES_REVENUE, CAT_ACTUAL_REVENUE, ROUND(100.0 * CAT_INV_CLOSING / NULLIF(SUM(CAT_INV_CLOSING) OVER (PARTITION BY REPORT_MONTH, HIERARCHY_LEVEL, LOCATION_ID), 0), 2) AS CAT_INV_SHARE_PCT, (CAT_SALES_REVENUE / NULLIF(CAT_SALES_UNITS, 0)) AS CAT_ASP FROM CATEGORY_AGGREGATES ), STORE_MONTHLY_TARGETS_RAW AS ( SELECT CAST(TRIM(BRANCH_CODE) AS VARCHAR) AS BRANCH_CODE, TO_CHAR( COALESCE( TRY_TO_DATE(TRIM(TARGET_MONTH), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(TARGET_MONTH), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(TARGET_MONTH), \'YYYY-MM-DD\') ), \'YYYY-MM\' ) AS REPORT_MONTH, AVG(CAST(REGEXP_REPLACE(TRIM(CUMULATIVE_TARGET_MTD), \'[^0-9.]\', \'\') AS NUMBER(18,2))) AS STORE_TARGET FROM SNITCH_DB.MAPLEMONK.MTD_TARGET_CLEAN WHERE TARGET_MONTH IS NOT NULL AND CUMULATIVE_TARGET_MTD IS NOT NULL AND COALESCE(TRY_TO_DATE(TRIM(TARGET_MONTH), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(TARGET_MONTH), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(TARGET_MONTH), \'YYYY-MM-DD\')) >= \'2026-04-01\' GROUP BY CAST(TRIM(BRANCH_CODE) AS VARCHAR), TO_CHAR(COALESCE(TRY_TO_DATE(TRIM(TARGET_MONTH), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(TARGET_MONTH), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(TARGET_MONTH), \'YYYY-MM-DD\')), \'YYYY-MM\') ), STORE_ZONE_MAP_CLEAN AS ( SELECT CAST(BRANCH_CODE AS VARCHAR) AS BRANCH_CODE, CLUSTER_NAME FROM SNITCH_DB.MAPLEMONK.STORE_ZONE_MAP QUALIFY ROW_NUMBER() OVER ( PARTITION BY CAST(BRANCH_CODE AS VARCHAR) ORDER BY CASE WHEN CLUSTER_NAME IS NULL OR TRIM(CLUSTER_NAME) = \'\' THEN 1 ELSE 0 END, CLUSTER_NAME ) = 1 ), HIERARCHY_TARGETS AS ( SELECT \'3. Store Wise\' AS HIERARCHY_LEVEL, S.BRANCH_CODE AS LOCATION_ID, S.REPORT_MONTH, S.STORE_TARGET FROM STORE_MONTHLY_TARGETS_RAW S UNION ALL SELECT \'2. Cluster Wise\' AS HIERARCHY_LEVEL, COALESCE(M.CLUSTER_NAME, \'OTHERS\') AS LOCATION_ID, S.REPORT_MONTH, SUM(S.STORE_TARGET) AS STORE_TARGET FROM STORE_MONTHLY_TARGETS_RAW S LEFT JOIN STORE_ZONE_MAP_CLEAN M ON S.BRANCH_CODE = M.BRANCH_CODE GROUP BY COALESCE(M.CLUSTER_NAME, \'OTHERS\'), S.REPORT_MONTH UNION ALL SELECT \'1. Company Wide\' AS HIERARCHY_LEVEL, \'ALL STORES\' AS LOCATION_ID, S.REPORT_MONTH, SUM(S.STORE_TARGET) AS STORE_TARGET FROM STORE_MONTHLY_TARGETS_RAW S GROUP BY S.REPORT_MONTH ), CATEGORY_TARGET_METRICS AS ( SELECT CP.REPORT_MONTH, CP.HIERARCHY_LEVEL, CP.LOCATION_ID, CP.CATEGORY, HT.STORE_TARGET AS STORE_MONTHLY_TARGET, (CP.CAT_INV_SHARE_PCT * CP.CAT_ASP) AS RAW_TARGET_WEIGHT, ROUND(100.0 * (CP.CAT_INV_SHARE_PCT * CP.CAT_ASP) / NULLIF( SUM(CP.CAT_INV_SHARE_PCT * CP.CAT_ASP) OVER (PARTITION BY CP.REPORT_MONTH, CP.HIERARCHY_LEVEL, CP.LOCATION_ID), 0 ), 4) AS WEIGHTED_CAT_TARGET_PCT, ROUND(HT.STORE_TARGET * ( (CP.CAT_INV_SHARE_PCT * CP.CAT_ASP) / NULLIF( SUM(CP.CAT_INV_SHARE_PCT * CP.CAT_ASP) OVER (PARTITION BY CP.REPORT_MONTH, CP.HIERARCHY_LEVEL, CP.LOCATION_ID), 0 ) ), 2) AS CATEGORY_TARGET, ROUND(100.0 * CP.CAT_ACTUAL_REVENUE / NULLIF( HT.STORE_TARGET * ( (CP.CAT_INV_SHARE_PCT * CP.CAT_ASP) / NULLIF( SUM(CP.CAT_INV_SHARE_PCT * CP.CAT_ASP) OVER (PARTITION BY CP.REPORT_MONTH, CP.HIERARCHY_LEVEL, CP.LOCATION_ID), 0 ) ), 0 ), 2) AS TARGET_PCT_ACHIEVED FROM CATEGORY_PERF_CALC CP LEFT JOIN HIERARCHY_TARGETS HT ON CP.HIERARCHY_LEVEL = HT.HIERARCHY_LEVEL AND CP.LOCATION_ID = HT.LOCATION_ID AND CP.REPORT_MONTH = HT.REPORT_MONTH ) SELECT M.*, T.STORE_MONTHLY_TARGET, T.RAW_TARGET_WEIGHT, T.WEIGHTED_CAT_TARGET_PCT, T.CATEGORY_TARGET, T.TARGET_PCT_ACHIEVED FROM MASTER_DATA M LEFT JOIN CATEGORY_TARGET_METRICS T ON M.REPORT_MONTH = T.REPORT_MONTH AND M.HIERARCHY_LEVEL = T.HIERARCHY_LEVEL AND M.LOCATION_ID = T.LOCATION_ID AND M.CATEGORY = T.CATEGORY;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            